// 先准备三条用户记录。每条记录都用一个对象表示，像数据库里的一行资料。
const users = [
  { name: "小雨", city: "上海" },
  { name: "小林", city: "北京" },
  { name: "小周", city: "广州" }
];

// 现在提出一个问题：请找到名字是“小林”的那条记录。
// find 会从前往后检查，找到符合条件的记录后就返回它。
const wantedUser = users.find((user) => user.name === "小林");

console.log("找到的用户:", wantedUser);
console.log("这个小例子说明：数据保存好以后，程序可以按照条件取回它。");

// 每个对象代表 students 表中的一行。
const students = [
  { name: "小雨", city: "上海", age: 18 },
  { name: "小林", city: "北京", age: 19 },
  { name: "小周", city: "北京", age: 18 }
];

// filter 会保留所有符合条件的行，而不是只保留第一行。
// 这里的条件是：city 这一列的值必须等于“北京”。
const studentsInBeijing = students.filter((student) => student.city === "北京");

console.log("住在北京的学生:", studentsInBeijing);
console.log("一张表可以有很多行，每一行都有相同的列。");

components.example:
```sql
-- 查看：找到住在北京的学生
SELECT name FROM students WHERE city = '北京';

-- 添加：登记一位新学生
INSERT INTO students (name, city, age)
VALUES ('小陈', '深圳', 18);

-- 修改：把小林的城市改成杭州
UPDATE students SET city = '杭州' WHERE name = '小林';

-- 删除：移除小陈这条记录
DELETE FROM students WHERE name = '小陈';
```

每条语句都可以先用自然语言读一遍，再检查它会影响哪些记录。尤其是 UPDATE 和 DELETE，`WHERE` 条件决定了修改或删除的范围。

components.code:
// 这组数据模拟数据库里的 students 表。
let students = [
  { name: "小雨", city: "上海" },
  { name: "小林", city: "北京" }
];

// SELECT：查看住在北京的记录，不改变原来的数据。
console.log("查询结果:", students.filter((student) => student.city === "北京"));

// INSERT：添加一条新记录，就像新同学来报名。
students.push({ name: "小周", city: "广州" });

// UPDATE：找到小林，只修改他的城市。
const studentToUpdate = students.find((student) => student.name === "小林");
if (studentToUpdate) {
  studentToUpdate.city = "杭州";
}

// DELETE：保留不是小周的记录，相当于删除小周。
students = students.filter((student) => student.name !== "小周");

console.log("最后的学生表:", students);
